import hashlib, json, pathlib, re
p = pathlib.Path('docs/evidence/heb-154/agent-code-v2/physical-runtime-binding.md')
doc = p.read_text()
expected = ['EN-access', 'EN-route', 'EN-scope', 'EN-custody', 'EN-lifecycle']
def check(text):
    if re.findall(r'^#### (EN-[a-z]+) — ', text, re.M) != expected:
        raise ValueError('enrollment_heading_membership')
check(doc)
controls = []
for name, changed in [('missing_enrollment_heading', doc.replace('#### EN-access — ', '#### omitted — ', 1)), ('duplicate_enrollment_heading', doc + '\n#### EN-access — duplicate\n')]:
    try:
        check(changed)
    except ValueError as exc:
        assert str(exc) == 'enrollment_heading_membership'
        controls.append(name)
    else:
        raise AssertionError(name)
print(json.dumps({'scope': 'All EN proposal headings in the complete physical-binding document, exact membership and order only; not ratification, prose correctness, implementation completeness or access enforcement.', 'result': 'enrollment_heading_inventory_passed', 'decision_ids': expected, 'authoring_dirty_controls_detected': controls, 'physical_runtime_sha256': hashlib.sha256(p.read_bytes()).hexdigest()}, indent=2))
